import json,re
from collections import Counter
_WS=re.compile(r'\s+')
for t in ['task_000506_c13429e7','task_001016_b1b861c4','task_002108_a8cfbf2a','task_000910_16cc0daf']:
    m=json.load(open(t+'.messages.json'))
    cmds=[]
    for msg in m:
        for tc in (msg.get('tool_calls') or []):
            args=tc.get('function',{}).get('arguments','')
            try: a=json.loads(args)
            except: a={}
            c=a.get('command','')
            if c: cmds.append(_WS.sub(' ',c.strip())[:400])
    ctr=Counter(cmds)
    top=ctr.most_common(3)
    print(t,'total_cmds=',len(cmds),'unique=',len(ctr),'top_counts=',[v for _,v in top])
"

